// Embedded antialiased bitmap fonts (generated by ps3/tools/gen_font.py).
#ifndef CHIAKI_PS3_FONT_H
#define CHIAKI_PS3_FONT_H

#include <stdint.h>

typedef struct
{
	uint32_t offset;  // into the alpha array
	uint16_t w, h;    // bitmap size
	int16_t left;     // bitmap x offset from the pen position
	int16_t top;      // bitmap y offset from the line top
	int16_t advance;
} FontGlyph;

typedef struct
{
	int size;
	int ascent, descent;
	int first, last;
	const FontGlyph *glyphs;
	const uint8_t *alpha;
} Font;

extern const Font font_small;   // 20 px
extern const Font font_normal;  // 26 px
extern const Font font_bold;    // 26 px bold
extern const Font font_title;   // 40 px bold

#endif
